export const colors = {
  background: '#0B1026',
  surface: '#141B3A',
  primary: '#00D4FF',
  secondary: '#7A5CFF',
  text: '#FFFFFF',
  muted: '#98A3C5',
  danger: '#FF5C7A',
  success: '#2DD4BF',
  warning: '#F59E0B',
  card: '#172144',
  border: '#233063',
};

export const spacing = {
  xxs: 4,
  xs: 8,
  sm: 12,
  md: 16,
  lg: 24,
  xl: 32,
  xxl: 40,
};

export const shadow = {
  shadowColor: '#000',
  shadowOffset: { width: 0, height: 14 },
  shadowOpacity: 0.12,
  shadowRadius: 30,
  elevation: 8,
};

export const gradient = ['#0B1026', '#141B3A'];
